import struct, subprocess, tempfile, os, signal,itertools
B='/workspace/artifacts/target/jasper'

def m(marker, body): return b'\xff'+bytes([marker])+struct.pack('>H',len(body)+2)+body

def siz(width=1,height=1,tw=1,th=1,numcomps=1,xrsiz=1,yrsiz=1):
    body=struct.pack('>HIIIIIIIIH',0,width,height,0,0,tw,th,0,0,numcomps)+b''.join(bytes([7,xrsiz,yrsiz]) for _ in range(numcomps))
    return m(0x51,body)

def cod(layers=1, dlvls=0, cbw=2, cbh=2, cstyle=0, xform=1, scod=0, prog=0, mct=0):
    body=struct.pack('>BBHB',scod,prog,layers,mct)+bytes([dlvls,cbw,cbh,cstyle,xform])
    return m(0x52,body)

def qcd(style=0, guard=2, vals=b'\x00'):
    return m(0x5c, bytes([(guard<<5)|style])+vals)

def sot(tile=0, partlen=0, partno=0, parts=1):
    body=struct.pack('>HIBB',tile,partlen,partno,parts)
    return m(0x90,body)

def run(name,data):
    fd,path=tempfile.mkstemp(suffix='.jpc'); os.write(fd,data); os.close(fd)
    try:
      cp=subprocess.run([B,'-f',path,'-t','jpc','-F','/dev/null','-T','pnm'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=5)
      sig=signal.Signals(-cp.returncode).name if cp.returncode<0 else ''
      print('\n---',name,'len',len(data),'rc',cp.returncode,sig)
      print(cp.stdout.decode('latin1','replace')[:200])
      print(cp.stderr.decode('latin1','replace')[:1200])
    except subprocess.TimeoutExpired: print('TIMEOUT',name)
    os.unlink(path)

base=b'\xff\x4f'+siz()
for name,data in [
 ('cod_valid_eoc', base+cod()+qcd()+b'\xff\xd9'),
 ('cod_layers0_eoc', base+cod(layers=0)+qcd()+b'\xff\xd9'),
 ('cod_dlvls33_eoc', base+cod(dlvls=33)+qcd()+b'\xff\xd9'),
 ('cod_cbw0_eoc', base+cod(cbw=0)+qcd()+b'\xff\xd9'),
 ('cod_cbh0_eoc', base+cod(cbh=0)+qcd()+b'\xff\xd9'),
 ('sot_sod_eoc', base+cod()+qcd()+sot(partlen=0)+b'\xff\x93'+b'\xff\xd9'),
 ('sot_sod_ff', base+cod()+qcd()+sot(partlen=0)+b'\xff\x93'+b'\x00'*10+b'\xff\xd9'),
]: run(name,data)
